def load_yaml_file(config_file_path, config_file):
    """
    Loads a yaml configuration file.

    :param config_file_path: Path of the configuration file.
    :param config_file: Configuration file object.
    :returns: Dictionary representation of the configuration file.
    """
    with open(config_file_path, "r") as config_file_handle:
        return yaml.safe_load(config_file_handle)


def load_ini_file(config_file_path, config_file):
    """
    Loads an .INI file.

    :param config_file_path: Path of the configuration file.
    :param config_file: Configuration file object.
    :returns: Dictionary representation of the configuration file.
    """
    config_file.read(config_file_path)
    config_dict = {}
    for section in config_file.sections():
        config_dict[section] = {}
        for option in config_file.options(section):
            config_dict[section][option] = config_file.get(section, option)
    return config_dict


